label("$O$",(0,5),W);
label("2",(0.9,2.3),S);
label("1",(0.5,5.2),S);
label("$A$",A,N);
draw((0,5)--D,linewidth(0.5));
draw((0,2)--G,linewidth(0.5));
label("$D$'",G,NE);
label("$D$",D,NE);
label("$B$",B,SW);
label("$C$",C,SE);
[/asy]


